/*
 * Demo datasets. Each is generated by real formulas, exported as plain values,
 * and then has a few human typos planted in it. `truth` records exactly what was
 * planted, so the test-suite can check that Unbake finds it — and nothing else.
 */
(function (global) {
  'use strict';

  function rng(seed) {
    return function () {
      seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  const r2 = (x) => Math.sign(x) * Math.round(Math.abs(x) * 100 * (1 + 1e-12)) / 100;
  const money = (x) => (x < 0 ? '-' : '') + '$' + Math.abs(x).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const csvRow = (cells) => cells.map((c) => (/[",\n]/.test(c) ? '"' + String(c).replace(/"/g, '""') + '"' : c)).join(',');
  const pick = (R, arr) => arr[Math.floor(R() * arr.length)];
  // change one digit of a number (keeps length, never makes a leading zero)
  function digitTypo(x) {
    const s = x.toFixed(2).split('');
    for (let i = 0; i < s.length; i++) {
      if (/\d/.test(s[i]) && s[i] !== '0' && i > 0) { s[i] = String((+s[i] + 4) % 10); break; }
    }
    return parseFloat(s.join(''));
  }

  // ------------------------------------------------------------------ invoices
  function invoices() {
    const R = rng(42);
    const skus = { 'LMP-200': 34.5, 'DSK-110': 289, 'CHR-031': 149.99, 'MON-27Q': 329.95, 'KBD-08': 59.9, 'CBL-4K': 12.75 };
    const rates = { CA: 0.0725, TX: 0.0625, NY: 0.04, WA: 0.065, OR: 0 };
    const customers = [['Halvorsen Labs', 'WA'], ['Brightline Dental', 'CA'], ['Okafor & Sons', 'TX'], ['Peregrine Studio', 'NY'],
      ['Mesa Verde Cafe', 'CA'], ['Tidewater Supply', 'OR'], ['Juniper Analytics', 'TX'], ['North Loop Clinic', 'NY'], ['Cobalt Freight', 'WA']];
    const header = ['Invoice', 'Date', 'Customer', 'State', 'SKU', 'Qty', 'Unit Price', 'Subtotal', 'Disc %', 'Discount', 'Net', 'Tax', 'Total'];
    const lines = [csvRow(header)];
    const truth = [];
    for (let i = 0; i < 36; i++) {
      const [cust, st] = pick(R, customers);
      let sku = pick(R, Object.keys(skus));
      let qty = 1 + Math.floor(R() * 9);
      let disc = pick(R, [0, 0, 0.05, 0.1]);
      if (i === 6) sku = 'MON-27Q';
      if (i === 14) { qty = 12; sku = 'KBD-08'; }
      if (i === 21) { disc = 0.1; sku = 'DSK-110'; qty = 3; }
      const price = skus[sku];
      const sub = r2(qty * price), dsc = r2(sub * disc), net = r2(sub - dsc), tax = r2(net * rates[st]), total = r2(net + tax);
      let shown = { qty, price, sub, dsc, net, tax, total };
      const rowNum = i + 2;
      if (i === 6) { shown.price = 239.95; truth.push({ col: 'Unit Price', row: rowNum, suggested: 329.95, kind: 'swap' }); }
      if (i === 14) { shown.qty = 21; truth.push({ col: 'Qty', row: rowNum, suggested: 12, kind: 'swap' }); }
      if (i === 21) { shown.dsc = digitTypo(dsc); truth.push({ col: 'Discount', row: rowNum, suggested: dsc, kind: 'digit' }); }
      if (i === 29) { shown.total = r2(total * 10); truth.push({ col: 'Total', row: rowNum, suggested: total, kind: 'decimal' }); }
      const date = new Date(Date.UTC(2026, 6, 1 + Math.floor(i * 1.6))).toISOString().slice(0, 10);
      lines.push(csvRow([String(10240 + i), date, cust, st, sku, String(shown.qty), money(shown.price), money(shown.sub),
        Math.round(disc * 100) + '%', money(shown.dsc), money(shown.net), money(shown.tax), money(shown.total)]));
    }
    return {
      id: 'invoices', title: 'Invoice export', icon: '🧾',
      blurb: '36 order lines exported from a billing system. Prices, discounts, state sales tax — all just numbers now.',
      csv: lines.join('\n') + '\n',
      truth: {
        formulas: {
          Invoice: 'Invoice = previous Invoice + 1',
          'Unit Price': 'lookup(SKU)', Subtotal: 'round(Qty × Unit Price, 2)', Discount: 'round(Subtotal × Disc %, 2)',
          Net: 'Subtotal − Discount', Tax: 'round(Net × rate(State), 2)', Total: 'Net + Tax',
        },
        rates, prices: skus, corrections: truth,
      },
    };
  }

  // ------------------------------------------------------------------ ledger
  function ledger() {
    const R = rng(7);
    const header = ['Date', 'Description', 'Category', 'Deposit', 'Withdrawal', 'Balance'];
    const lines = [csvRow(header)];
    const items = [
      ['Payroll — Acme Robotics', 'Income', 'in', 2450, 2450], ['Rent — Larkspur Apts', 'Housing', 'out', 1675, 1675],
      ['Whole Foods Market', 'Groceries', 'out', 38, 164], ['Trader Joe’s', 'Groceries', 'out', 22, 97],
      ['PG&E Utilities', 'Utilities', 'out', 61, 143], ['Comcast Internet', 'Utilities', 'out', 79.99, 79.99],
      ['Shell Gas', 'Transport', 'out', 31, 72], ['Freelance — Ruiz Design', 'Income', 'in', 300, 1200],
      ['Venmo from Priya', 'Transfers', 'in', 20, 140], ['Blue Bottle Coffee', 'Dining', 'out', 4.5, 18],
      ['REI Co-op', 'Shopping', 'out', 40, 260], ['Spotify', 'Subscriptions', 'out', 11.99, 11.99],
    ];
    let bal = 4210.55;
    const truth = [];
    lines.push(csvRow(['2026-03-01', 'Opening balance', 'Opening', '', '', money(bal)]));
    let totDep = 0, totWd = 0;
    for (let i = 1; i < 52; i++) {
      const [desc, cat, dir, lo, hi] = i % 14 === 1 ? items[0] : i % 14 === 3 ? items[1] : pick(R, items.slice(2));
      const amt = r2(lo + R() * (hi - lo));
      const dep = dir === 'in' ? amt : 0, wd = dir === 'out' ? amt : 0;
      bal = r2(bal + dep - wd);
      let shownWd = wd, shownBal = bal;
      const rowNum = i + 2;
      if (i === 17) {
        // two adjacent digits of the balance swapped while re-keying it
        const s = bal.toFixed(2).split('');
        const j = s.findIndex((ch, k) => k + 1 < s.length && /\d/.test(ch) && /\d/.test(s[k + 1]) && ch !== s[k + 1]);
        const t = s[j]; s[j] = s[j + 1]; s[j + 1] = t;
        shownBal = parseFloat(s.join(''));
        truth.push({ col: 'Balance', row: rowNum, suggested: bal, kind: 'swap' });
      }
      if (i === 33 && wd > 0) { shownWd = digitTypo(wd); truth.push({ col: 'Withdrawal', row: rowNum, suggested: wd, kind: 'digit' }); }
      totDep = r2(totDep + dep); totWd = r2(totWd + shownWd);
      const date = new Date(Date.UTC(2026, 2, 1 + Math.floor(i * 1.15))).toISOString().slice(0, 10);
      lines.push(csvRow([date, desc, cat, dep ? money(dep) : '', shownWd ? money(shownWd) : '', money(shownBal)]));
    }
    lines.push(csvRow(['', 'Total', '', money(totDep), money(totWd), '']));
    return {
      id: 'ledger', title: 'Bank ledger', icon: '🏦',
      blurb: 'A checking-account register someone retyped from statements, with a Total line at the bottom.',
      csv: lines.join('\n') + '\n',
      truth: { formulas: { Balance: 'previous Balance + Deposit − Withdrawal' }, corrections: truth },
    };
  }

  // ------------------------------------------------------------------ payroll
  function payroll() {
    const R = rng(2026);
    const header = ['Employee', 'Dept', 'Plan', 'Hours', 'OT Hours', 'Rate', 'Gross', 'Tax', 'Benefits', 'Net'];
    const lines = [csvRow(header)];
    const plans = { Basic: 45, Plus: 85, Family: 160 };
    const first = ['Ada', 'Bram', 'Chen', 'Dana', 'Eli', 'Fatima', 'Gus', 'Hana', 'Ivo', 'Jules', 'Kemal', 'Lena', 'Mo', 'Nia', 'Oren',
      'Pia', 'Quinn', 'Rafa', 'Sol', 'Tess', 'Uma', 'Vik', 'Wren', 'Xan', 'Yara', 'Zed', 'Amir', 'Bea', 'Cruz', 'Dev'];
    const truth = [];
    for (let i = 0; i < 30; i++) {
      const dept = pick(R, ['Ops', 'Ops', 'Support', 'Warehouse', 'Design']);
      const plan = pick(R, Object.keys(plans));
      let hours = pick(R, [40, 40, 40, 38, 36, 32, 37.5]);
      let ot = R() < 0.55 ? pick(R, [2, 2.5, 4, 5.5, 6, 8]) : 0;
      if (i === 4) ot = 2.5;
      if (i === 25) { hours = 38; }
      if (i === 11) { /* ensure Plus */ }
      const plan2 = i === 11 ? 'Plus' : plan;
      const rate = pick(R, [18.5, 21, 22.75, 24.4, 27.25, 31, 34.8]);
      const gross = r2(hours * rate + 1.5 * ot * rate), tax = r2(gross * 0.22), ben = plans[plan2], net = r2(gross - tax - ben);
      const s = { hours, ot, gross, tax, ben, net };
      const rowNum = i + 2;
      if (i === 4) { s.ot = 25; truth.push({ col: 'OT Hours', row: rowNum, suggested: 2.5, kind: 'decimal' }); }
      if (i === 11) { s.ben = 58; truth.push({ col: 'Benefits', row: rowNum, suggested: 85, kind: 'swap' }); }
      if (i === 19) {
        const str = net.toFixed(2); s.net = parseFloat(str.slice(0, 1) + str.slice(2));
        truth.push({ col: 'Net', row: rowNum, suggested: net, kind: 'dropped' });
      }
      if (i === 25) { s.hours = 83; truth.push({ col: 'Hours', row: rowNum, suggested: 38, kind: 'swap' }); }
      lines.push(csvRow([first[i] + ' ' + String.fromCharCode(65 + ((i * 7) % 26)) + '.', dept, plan2, String(s.hours), s.ot.toFixed(1),
        money(rate), money(s.gross), money(s.tax), money(s.ben), money(s.net)]));
    }
    return {
      id: 'payroll', title: 'Payroll run', icon: '💼',
      blurb: 'One pay period for 30 people: overtime at time-and-a-half, flat tax, benefit plans.',
      csv: lines.join('\n') + '\n',
      truth: {
        formulas: { Gross: 'round(Hours × Rate + 1.5 × OT Hours × Rate, 2)', Tax: 'round(0.22 × Gross, 2)', Benefits: 'lookup(Plan)', Net: 'Gross − Tax − Benefits' },
        corrections: truth,
      },
    };
  }

  const api = { all: () => [invoices(), ledger(), payroll()] };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else global.UnbakeSamples = api;
})(typeof window !== 'undefined' ? window : globalThis);
